<script setup>

    import { ref } from 'vue';
    import { useUsuarioStore } from '@/stores/usuarios';
    import { VueSignaturePad } from '@selemondev/vue3-signature-pad';

    const signaturePad = ref(null);
    const signatureData = ref('');
    const storeUsuario = useUsuarioStore();
    const options = ref({
        penColor: '#0000ff',
        backgroundColor: 'rgb(255, 255, 255)',
        maxWidth: 1,
        minWidth: 1
    })

    const blankSignature = 'data:image/png;base64,';

    const limpiarFirma = () => {
        signaturePad.value.undo();
        signatureData.value = null;
    }

    const guardarFirma = () => {

        const result = signaturePad.value.saveSignature()
        if(result === blankSignature){
            storeUsuario.MostrarMensaje('error', 'No ha realizado la firma')
        }else{
            signatureData.value = result;
            signaturePad.value.undo();
            storeUsuario.MostrarMensaje('success', 'Se ha registrado su firma correctamente')
        }
        

    }

</script>

<template>
    <div>
        <h1>Acta de aceptación</h1>

        <VueSignaturePad
            ref="signaturePad"
            width="500px"
            height="200px"
            :max-width="2"
            :min-width="1"
            :options="options"
        />

    </div>

    <button @click="limpiarFirma()">Limpiar</button>
    <button @click="guardarFirma()">Guardar</button>

    <img v-if="signatureData" :src="signatureData" alt="">
</template>


